CREATE TABLE writing_profiles(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),role TEXT NOT NULL,route_fingerprint TEXT NOT NULL,capability_json TEXT NOT NULL,configuration_json TEXT NOT NULL,evaluation_ref TEXT,qualification TEXT NOT NULL,expires_on_change_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE diagnostic_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),dataset_hash TEXT NOT NULL,profile_id TEXT REFERENCES writing_profiles(id),policy_json TEXT NOT NULL,status TEXT NOT NULL,report_blob TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE diagnostic_items(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES diagnostic_runs(id),case_id TEXT NOT NULL,variant_id TEXT NOT NULL,repetition INTEGER NOT NULL,input_hash TEXT NOT NULL,generation_run_ids_json TEXT NOT NULL,result_blob TEXT,human_review_json TEXT,task_id TEXT REFERENCES tasks(id),status TEXT NOT NULL,UNIQUE(run_id,case_id,variant_id,repetition));
